function buildModuleWiring(design, assembly) {
  // The legacy builder only validates its own wire IDs. Module feeders are
  // restored by the extension, including their saved section/disconnection.
  const baseDesign={...design,
    disconnected:(design.disconnected||[]).filter(id=>!/^module-(feed|wire):/.test(id)),
    wireOverrides:Object.fromEntries(Object.entries(design.wireOverrides||{}).filter(([id])=>!/^module-(feed|wire):/.test(id))),
  };
  return applyModuleWiring(applyModuleFeeds(buildWiring(baseDesign,assembly),design),design);
}

function auditModuleWiring(net, design) {
  const special=net.wires.filter(w=>['dc','comms'].includes(w.class));
  const results=auditWiring({...net,wires:net.wires.filter(w=>!['dc','comms'].includes(w.class))},design);
  for(const wire of special) {
    const from=net.ports[wire.from],to=net.ports[wire.to];
    if(!wire.connected) results.push({level:'error',code:'OPEN_WIRE',text:`${wire.scope} 断开：${wire.from} → ${wire.to}`,wire:wire.id});
    if(Number.isFinite(wire.section) && (wire.section<Math.max(from.minWire,to.minWire) || wire.section>Math.min(from.maxWire,to.maxWire))) {
      results.push({level:'error',code:'WIRE_TERMINAL',text:`${wire.from} → ${wire.to} 的 ${wire.section} mm² 超出端子范围。`,wire:wire.id});
    }
  }
  return [...results,...(net.wiringIssues||[])];
}

